  /**
   * @method
   * @name krakenfutures#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://docs.kraken.com/api/docs/futures-api/trading/get-order-status/
   * @param {string} id the order id
   * @param {string} symbol unified market symbol that the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrder(std::any id, std::any symbol = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{
                     {std::string("orderIds"), ccxt::list{id}},
                 };
                 std::any orders = awaitValue(
                     this->fetchOrders(std::any{}, std::any{}, std::any{},
                                       this->extend(request, params)));
                 std::any order = this->safeDict(orders, 0);
                 if (isTrue(isEqual(order, std::any{}))) {
                   throw OrderNotFound(toString(add(
                       add(this->id,
                           std::string(" fetchOrder could not find order id ")),
                       id)));
                 }
                 return order;
               })
        .share();
  }

  /**
   * @method
   * @name krakenfutures#fetchClosedOrders
   * @see https://docs.kraken.com/api-reference/account-history/get-order-events
   * @see
   * https://docs.kraken.com/api-reference/account-history/get-trigger-events
   * @description Gets all closed orders, including trigger orders, for an
   * account from the exchange api
   * @param {string} symbol Unified market symbol
   * @param {int} [since] Timestamp (ms) of earliest order.
   * @param {int} [limit] How many orders to return.
   * @param {object} [params] Exchange specific parameters
   * @param {bool} [params.trigger] set to true if you wish to fetch only
   * trigger orders
   * @returns An array of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("since"), since);
                 }
                 std::any isTrigger =
                     this->safeBool2(params, std::string("trigger"),
                                     std::string("stop"), false);
                 std::any response = std::any{};
                 if (isTrue(isEqual(isTrigger, true))) {
                   params =
                       this->omit(params, ccxt::list{std::string("trigger"),
                                                     std::string("stop")});
                   response = awaitValue(
                       this->historyGetTriggers(this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->historyGetOrders(this->extend(request, params)));
                 }
                 std::any allOrders = this->safeList(
                     response, std::string("elements"), ccxt::list{});
                 std::any closedOrders = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(allOrders));
                      postFixIncrement(i)) {
                   std::any order = ::getValue(allOrders, i);
                   std::any event = this->safeDict(order, std::string("event"),
                                                   ccxt::dict{});
                   std::any orderPlaced =
                       this->safeDict2(event, std::string("OrderPlaced"),
                                       std::string("OrderTriggerActivated"));
                   std::any orderUpdated =
                       this->safeDict(event, std::string("OrderUpdated"));
                   if (isTrue(!isEqual(orderPlaced, std::any{}))) {
                     std::any innerOrder = this->safeDict(
                         orderPlaced, std::string("order"), ccxt::dict{});
                     std::any filled =
                         this->safeString(innerOrder, std::string("filled"));
                     if (isTrue(!isEqual(filled, std::string("0")))) {
                       ::setValue(
                           innerOrder, std::string("status"),
                           std::string("closed")); // status not available in
                                                   // the response
                       arrayPush(closedOrders, innerOrder);
                     }
                   } else if (isTrue(!isEqual(orderUpdated, std::any{}))) {
                     std::any reason =
                         this->safeString(orderUpdated, std::string("reason"));
                     if (isTrue(isEqual(reason, std::string("full_fill")))) {
                       std::any newOrder = this->safeDict(
                           orderUpdated, std::string("newOrder"), ccxt::dict{});
                       ::setValue(newOrder, std::string("status"),
                                  std::string("closed"));
                       arrayPush(closedOrders, newOrder);
                     }
                   }
                 }
                 return this->parseOrders(closedOrders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name krakenfutures#fetchCanceledOrders
   * @see https://docs.kraken.com/api/docs/futures-api/history/get-order-events
   * @description Gets all canceled orders, including trigger orders, for an
   * account from the exchange api
   * @param {string} symbol Unified market symbol
   * @param {int} [since] Timestamp (ms) of earliest order.
   * @param {int} [limit] How many orders to return.
   * @param {object} [params] Exchange specific parameters
   * @param {bool} [params.trigger] set to true if you wish to fetch only
   * trigger orders
   * @returns An array of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchCanceledOrders(std::any symbol = std::any{}, std::any since = std::any{},
                      std::any limit = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("from"), since);
                 }
                 std::any response = std::any{};
                 std::any isTrigger =
                     this->safeBool2(params, std::string("trigger"),
                                     std::string("stop"), false);
                 if (isTrue(isEqual(isTrigger, true))) {
                   params =
                       this->omit(params, ccxt::list{std::string("trigger"),
                                                     std::string("stop")});
                   response = awaitValue(
                       this->historyGetTriggers(this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->historyGetOrders(this->extend(request, params)));
                 }
                 std::any allOrders = this->safeList(
                     response, std::string("elements"), ccxt::list{});
                 std::any canceledAndRejected = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(allOrders));
                      postFixIncrement(i)) {
                   std::any order = ::getValue(allOrders, i);
                   std::any event = this->safeDict(order, std::string("event"),
                                                   ccxt::dict{});
                   std::any isCancelledTriggerOrder =
                       (inOp(event, std::string("OrderTriggerCancelled")));
                   std::any orderPlaced =
                       this->safeDict2(event, std::string("OrderPlaced"),
                                       std::string("OrderTriggerCancelled"));
                   if (isTrue(!isEqual(orderPlaced, std::any{}))) {
                     std::any innerOrder = this->safeDict(
                         orderPlaced, std::string("order"), ccxt::dict{});
                     std::any filled =
                         this->safeString(innerOrder, std::string("filled"));
                     if (isTrue(isTrue(isEqual(filled, std::string("0"))) ||
                                isTrue(isCancelledTriggerOrder))) {
                       ::setValue(
                           innerOrder, std::string("status"),
                           std::string("canceled")); // status not available in
                                                     // the response
                       arrayPush(canceledAndRejected, innerOrder);
                     }
                   }
                   std::any orderCanceled =
                       this->safeDict(event, std::string("OrderCancelled"));
                   if (isTrue(!isEqual(orderCanceled, std::any{}))) {
                     std::any innerOrder = this->safeDict(
                         orderCanceled, std::string("order"), ccxt::dict{});
                     ::setValue(
                         innerOrder, std::string("status"),
                         std::string("canceled")); // status not available in
                                                   // the response
                     arrayPush(canceledAndRejected, innerOrder);
                   }
                   std::any orderRejected =
                       this->safeDict(event, std::string("OrderRejected"));
                   if (isTrue(!isEqual(orderRejected, std::any{}))) {
                     std::any innerOrder = this->safeDict(
                         orderRejected, std::string("order"), ccxt::dict{});
                     ::setValue(
                         innerOrder, std::string("status"),
                         std::string("rejected")); // status not available in
                                                   // the response
                     arrayPush(canceledAndRejected, innerOrder);
                   }
                 }
                 return this->parseOrders(canceledAndRejected, market, since,
                                          limit);
               })
        .share();
  }

  virtual std::any parseOrderType(std::any orderType) {
    std::any typesMap = ccxt::dict{
        {std::string("lmt"), std::string("limit")},
        {std::string("mkt"), std::string("market")},
        {std::string("post"), std::string("limit")},
        {std::string("ioc"), std::string("market")},
    };
    return this->safeString(typesMap, orderType, orderType);
  }

  virtual void verifyOrderActionSuccess(std::any status, std::any method,
                                        std::any omit = ccxt::list{}) {
    std::any errors = ccxt::dict{
        {std::string("invalidOrderType"), std::string("InvalidOrder")},
        {std::string("invalidSide"), std::string("InvalidOrder")},
        {std::string("invalidSize"), std::string("InvalidOrder")},
        {std::string("invalidPrice"), std::string("InvalidOrder")},
        {std::string("insufficientAvailableFunds"),
         std::string("InsufficientFunds")},
        {std::string("selfFill"), std::string("ExchangeError")},
        {std::string("tooManySmallOrders"), std::string("ExchangeError")},
        {std::string("maxPositionViolation"), std::string("BadRequest")},
        {std::string("marketSuspended"), std::string("ExchangeNotAvailable")},
        {std::string("marketInactive"), std::string("ExchangeNotAvailable")},
        {std::string("clientOrderIdAlreadyExist"),
         std::string("DuplicateOrderId")},
        {std::string("clientOrderIdTooLong"), std::string("BadRequest")},
        {std::string("outsidePriceCollar"), std::string("InvalidOrder")},
        {std::string("postWouldExecute"),
         std::string("OrderImmediatelyFillable")},
        {std::string("iocWouldNotExecute"), std::string("OrderNotFillable")},
        {std::string("wouldNotReducePosition"), std::string("ExchangeError")},
        {std::string("orderForEditNotFound"), std::string("OrderNotFound")},
        {std::string("orderForEditNotAStop"), std::string("InvalidOrder")},
        {std::string("filled"), std::string("OrderNotFound")},
        {std::string("notFound"), std::string("OrderNotFound")},
    };
    if (isTrue(isTrue((inOp(errors, status))) &&
               !isTrue(this->inArray(status, omit)))) {
      throwDynamicException(
          ::getValue(errors, status),
          add(add(add(add(this->id, std::string(": ")), method),
                  std::string(" failed due to ")),
              status));
    }
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("placed"), std::string("open")},
        {std::string("cancelled"), std::string("canceled")},
        {std::string("invalidOrderType"), std::string("rejected")},
        {std::string("invalidSide"), std::string("rejected")},
        {std::string("invalidSize"), std::string("rejected")},
        {std::string("invalidPrice"), std::string("rejected")},
        {std::string("insufficientAvailableFunds"), std::string("rejected")},
        {std::string("selfFill"), std::string("rejected")},
        {std::string("tooManySmallOrders"), std::string("rejected")},
        {std::string("maxPositionViolation"), std::string("rejected")},
        {std::string("marketSuspended"), std::string("rejected")},
        {std::string("marketInactive"), std::string("rejected")},
        {std::string("clientOrderIdAlreadyExist"), std::string("rejected")},
        {std::string("clientOrderIdTooLong"), std::string("rejected")},
        {std::string("outsidePriceCollar"), std::string("rejected")},
        {std::string("postWouldExecute"), std::string("rejected")},
        {std::string("iocWouldNotExecute"), std::string("rejected")},
        {std::string("wouldNotReducePosition"), std::string("rejected")},
        {std::string("edited"), std::string("open")},
        {std::string("orderForEditNotFound"), std::string("rejected")},
        {std::string("orderForEditNotAStop"), std::string("rejected")},
        {std::string("filled"), std::string("closed")},
        {std::string("notFound"), std::string("rejected")},
        {std::string("untouched"), std::string("open")},
        {std::string("partiallyFilled"), std::string("open")},
        {std::string("ENTERED_BOOK"), std::string("open")},
        {std::string("FULLY_EXECUTED"), std::string("closed")},
        {std::string("CANCELLED"), std::string("canceled")},
        {std::string("TRIGGER_PLACED"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("UNTOUCHED"), std::string("open")},
    };
    return this->safeString(statuses, status, status);
  }

