                     this->safeString(params, std::string("symbol"));
                 params = this->omit(params, ccxt::list{std::string("type"),
                                                        std::string("account"),
                                                        std::string("symbol")});
                 std::any response =
                     awaitValue(this->privateGetAccounts(params));
