                 //                "auxiliary": { usd: "0", pv: '0.0', pnl:
                 //                '0.0', af: '0.0', funding: "0.0" },
                 //                "marginRequirements": { im: '0.0', mm: '0.0',
                 //                lt: '0.0', tt: "0.0" }, "triggerEstimates": {
                 //                im: '0', mm: '0', lt: "0", tt: "0" },
